1	import { Block, Text } from "@prototyp/skeletor";
2	import { FlashList, type FlashListRef } from "@shopify/flash-list";
3	import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
4	import { useAtom } from "jotai";
5	import {
6	  addDateDividers,
7	  getEventId,
8	  getItemUniqueKey,
9	  groupInfoEvents,
10	} from "modules/matrix-client/utils";
11	import { useRoomIdentityViolations } from "modules/room/hooks";
12	import { useRoomTimeline } from "modules/timeline/hooks";
13	import { TimelineAtoms } from "modules/timeline/jotai";
14	import {
15	  filterSameStateKey,
16	  handleIsPreviousSameSender,
17	} from "modules/timeline/utils";
18	import {
19	  type FC,
20	  useCallback,
21	  useEffect,
22	  useMemo,
23	  useRef,
24	  useState,
25	} from "react";
26	import {
27	  Image,
28	  KeyboardAvoidingView,
29	  type NativeScrollEvent,
30	  type NativeSyntheticEvent,
31	  StyleSheet,
32	} from "react-native";
33	import {
34	  Button,
35	  Loading,
36	  MemberDetailsBottomSheet,
37	  SeenByBottomSheet,
38	} from "shared/components";
39	import { useMemberDetails } from "shared/hooks";
40	import { DateDivider } from "../date-divider";
41	import { GroupedInfoMessages } from "../grouped-info-messages";
42	import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
43	import { RoomIdentityBanner } from "../room-identity-banner";
44	import { RoomInput } from "../room-input";
45	import { SingleMessageType } from "../single-message-type";
46	
47	interface Props {
48	  room: RoomInterface;
49	  roomId: string;
50	}
51	
52	export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
53	  const flashListRef = useRef<FlashListRef<TimelineListItem>>(null);
54	  const isAtBottomRef = useRef(true);
55	  const lastEventKeyRef = useRef<string | undefined>(undefined);
56	  const lastBottomEventKeyRef = useRef<string | undefined>(undefined);
57	  const [showScrollDown, setShowScrollDown] = useState(false);
58	  const {
59	    events,
60	    loadingMessage,
61	    refreshing,
62	    updateTrigger,
63	    isDirect,
64	    loadMoreMessages,
65	    markAsRead,
66	  } = useRoomTimeline({
67	    room,
68	    roomId,
69	  });
70	  const [scrollToEventId, setScrollToEventId] = useAtom(
71	    TimelineAtoms.scrollToEventId,
72	  );
73	  const [seenByUserIds, setSeenByUserIds] = useAtom(
74	    TimelineAtoms.seenByUserIds,
75	  );
76	  const { isPinViolatingUsersLoading, violatingUsers, pinViolatingUsers } =
77	    useRoomIdentityViolations(room);
78	  const {
79	    selectedMember,
80	    isBottomSheetOpen,
81	    openMemberDetails,
82	    closeMemberDetails,
83	  } = useMemberDetails();
84	
85	  const sortedEvents = useMemo(() => {
86	    const sorted = [...events].sort(
87	      (a, b) => Number(a.timestamp) - Number(b.timestamp),
88	    );
89	
90	    return filterSameStateKey(sorted);
91	  }, [events]);
92	
93	  const eventsWithDividers = useMemo(() => {
94	    return groupInfoEvents(addDateDividers(sortedEvents));
95	  }, [sortedEvents]);
96	
97	  const handleScrollToEvent = useCallback(
98	    (eventId: string) => {
99	      const index = eventsWithDividers.findIndex(
100	        (item) => item.type === "event" && getEventId(item.data) === eventId,
101	      );
102	      if (index === -1) return;
103	
104	      flashListRef.current?.scrollToIndex({
105	        index,
106	        animated: true,
107	        viewPosition: 0.5,
108	      });
109	    },
110	    [eventsWithDividers],
111	  );
112	
113	  useEffect(() => {
114	    if (!scrollToEventId) return;
115	    handleScrollToEvent(scrollToEventId);
116	    setScrollToEventId(null);
117	  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
118	
119	  const handleLoadMore = async () => {
120	    setShowScrollDown(false);
121	    await loadMoreMessages();
122	  };
123	
124	  const handleScrollDown = () => {
125	    flashListRef.current?.scrollToEnd({ animated: true });
126	    setShowScrollDown(false);
127	  };
128	
129	  const handleOnScroll = ({
130	    nativeEvent,
131	  }: NativeSyntheticEvent<NativeScrollEvent>) => {
132	    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
133	    const paddingToBottom = 100;
134	    const atBottom =
135	      layoutMeasurement.height + contentOffset.y >=
136	      contentSize.height - paddingToBottom;
137	    isAtBottomRef.current = atBottom;
138	    if (!atBottom) return;
139	    setShowScrollDown(false);
140	    markAsRead();
141	  };
142	
143	  const handleContentSizeChange = () => {
144	    const lastEvent = sortedEvents[sortedEvents.length - 1];
145	    const lastEventKey = lastEvent
146	      ? (getItemUniqueKey(lastEvent) ?? undefined)
147	      : undefined;
148	    const isNewEvent = lastEventKey !== lastEventKeyRef.current;
149	    lastEventKeyRef.current = lastEventKey;
150	    const shouldScrollToEnd =
151	      (isNewEvent && !!lastEvent?.isOwn) || isAtBottomRef.current;
152	    if (!shouldScrollToEnd) return;
153	    setTimeout(() => {
154	      flashListRef.current?.scrollToEnd({ animated: false });
155	    }, 100);
156	  };
157	
158	  useEffect(() => {
159	    const lastEvent = sortedEvents[sortedEvents.length - 1];
160	    const lastEventKey = lastEvent
161	      ? (getItemUniqueKey(lastEvent) ?? undefined)
162	      : undefined;
163	    const isNewMessageAtBottom = lastEventKey !== lastBottomEventKeyRef.current;
164	    lastBottomEventKeyRef.current = lastEventKey;
165	    if (!isNewMessageAtBottom || isAtBottomRef.current || lastEvent?.isOwn) {
166	      return;
167	    }
168	    setShowScrollDown(true);
169	  }, [sortedEvents]);
170	
171	  return (
172	    <>
173	      <KeyboardAvoidingView style={styles.flex} behavior="padding">
174	        {!!violatingUsers.length && (
175	          <RoomIdentityBanner
176	            users={violatingUsers}
177	            isLoading={isPinViolatingUsersLoading}
178	            onDismiss={pinViolatingUsers}
179	          />
180	        )}
181	        {loadingMessage && <Loading />}
182	        <FlashList
183	          ref={flashListRef}
184	          data={eventsWithDividers}
185	          keyExtractor={(item) => {
186	            if (item.type === "divider") return item.id;
187	            if (item.type === "group") return item.id;
188	
189	            return getItemUniqueKey(item.data) ?? "";
190	          }}
191	          maintainVisibleContentPosition={{
192	            startRenderingFromBottom: true,
193	          }}
194	          extraData={updateTrigger}
195	          contentContainerStyle={styles.listContent}
196	          refreshing={refreshing}
197	          onContentSizeChange={handleContentSizeChange}
198	          onRefresh={handleLoadMore}
199	          onScroll={handleOnScroll}
200	          renderItem={({ item }) => {
201	            if (item.type === "divider") {
202	              return <DateDivider date={item.date} />;
203	            }
204	
205	            if (item.type === "group") {
206	              return (
207	                <GroupedInfoMessages events={item.events} roomId={roomId} />
208	              );
209	            }
210	
211	            return (
212	              <SingleMessageType
213	                roomId={roomId}
214	                event={item.data}
215	                isPreviousSameSender={handleIsPreviousSameSender(
216	                  isDirect,
217	                  sortedEvents,
218	                  item.data,
219	                )}
220	                onMemberPress={openMemberDetails}
221	              />
222	            );
223	          }}
224	        />
225	
226	        <RoomInput roomId={roomId} />
227	      </KeyboardAvoidingView>
228	
229	      <MessageContentBottomSheet roomId={roomId} />
230	
231	      <MemberDetailsBottomSheet
232	        isBottomSheetOpen={isBottomSheetOpen}
233	        selectedMember={selectedMember}
234	        roomId={roomId}
235	        onClose={closeMemberDetails}
236	      />
237	
238	      {showScrollDown && (
239	        <Block
240	          absolute
241	          offsets={{ right: 0, bottom: 100 }}
242	          align="center"
243	          justify="center"
244	          width="100%"
245	        >
246	          <Button.Outline size="medium" onPress={handleScrollDown}>
247	            <Text>New messages</Text>
248	            <Image source={require("assets/icons/arrow-down.png")} />
249	          </Button.Outline>
250	        </Block>
251	      )}
252	
253	      <SeenByBottomSheet
254	        isOpen={!!seenByUserIds}
255	        userIds={seenByUserIds ?? []}
256	        onClose={() => setSeenByUserIds(null)}
257	      />
258	    </>
259	  );
260	};
261	
262	const styles = StyleSheet.create({
263	  flex: {
264	    flex: 1,
265	  },
266	  listContent: {
267	    paddingHorizontal: 20,
268	    paddingTop: 12,
269	    paddingBottom: 20,
270	  },
271	});
